INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-autumn-am-01','exam-sg','情報セキュリティ組織・CSIRT','standard','single_choice','【平成30年度 秋期 午前 問1】組織的なインシデント対応体制の構築や運用を支援する目的でJPCERT/CCが作成したものはどれか。','[{"id":"a","text":"CSIRTマテリアル"},{"id":"b","text":"ISMSユーザーズガイド"},{"id":"c","text":"証拠保全ガイドライン"},{"id":"d","text":"組織における内部不正防止ガイドライン"}]','"a"','CSIRTマテリアルは，組織的なインシデント対応体制の構築・運用を支援するためにJPCERT/CCが作成した。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-02','exam-sg','ISMS・トップマネジメント','standard','single_choice','【平成30年度 秋期 午前 問2】JIS Q 27000:2014（情報セキュリティマネジメントシステム―用語）における，トップマネジメントに関する記述として，適切なものはどれか。','[{"id":"a","text":"ISMS適用範囲から独立した立場であることが求められる"},{"id":"b","text":"企業の場合，ISMS適用範囲にかかわらず代表取締役でなければならない"},{"id":"c","text":"情報システム部門の長でなければならない"},{"id":"d","text":"組織を指揮し，管理する人々の集まりとして複数名で構成されていてもよい"}]','"d"','トップマネジメントは組織を指揮・管理する人又は人々であり，複数名で構成される場合もある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-13','exam-sg','サイバー攻撃・ゼロデイ攻撃','standard','single_choice','【平成30年度 秋期 午前 問13】ゼロデイ攻撃の特徴はどれか。','[{"id":"a","text":"脆弱性に対してセキュリティパッチが提供される前に当該脆弱性を悪用して攻撃する"},{"id":"b","text":"特定のWebサイトに対し，日時を決めて，複数台のPCから同時に攻撃する"},{"id":"c","text":"特定のターゲットに対し，フィッシングメールを送信して不正サイトに誘導する"},{"id":"d","text":"不正中継が可能なメールサーバを見つけて，それを踏み台にチェーンメールを大量に送信する"}]','"a"','ゼロデイ攻撃は，修正パッチなどの対策が提供される前の脆弱性を悪用する攻撃。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-14','exam-sg','マルウェア・C&Cサーバ','standard','single_choice','【平成30年度 秋期 午前 問14】ボットネットにおけるC&Cサーバの役割として，適切なものはどれか。','[{"id":"a","text":"Webサイトのコンテンツをキャッシュし，本来のサーバに代わってコンテンツを利用することによって，ネットワークやサーバの負荷を軽減する"},{"id":"b","text":"外部からインターネットを経由して社内ネットワークにアクセスする際に，CHAPなどのプロトコルを用いることによって，利用者認証時のパスワードの盗聴を防止する"},{"id":"c","text":"外部からインターネットを経由して社内ネットワークにアクセスする際に，チャレンジレスポンス方式を採用したワンタイムパスワードを用いることによって，利用者認証時のパスワードの盗聴を防止する"},{"id":"d","text":"侵入して乗っ取ったコンピュータに対して，他のコンピュータへの攻撃などの不正な操作をするよう，外部から命令を出したり応答を受け取ったりする"}]','"d"','C&Cサーバは感染端末へ命令を送り，その応答を受け取ってボットネットを遠隔操作する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-15','exam-sg','マルウェア・WannaCry','standard','single_choice','【平成30年度 秋期 午前 問15】マルウェアWanna Cryptor（WannaCry）に関する記述として，適切なものはどれか。','[{"id":"a","text":"SMBv1の脆弱性を悪用するなどして感染し，PC内のデータを暗号化してデータの復号のための金銭を要求したり，他のPCに感染を拡大したりする"},{"id":"b","text":"ファイル共有など複数の感染経路を使って大量のPCに感染を拡大し，さらにPC内の電子メールアドレスを収集しながらインターネット経由で感染を拡大する"},{"id":"c","text":"ランダムにIPアドレスを選んでデータベースの脆弱性を悪用した攻撃を行うことによって多数のPCに感染を拡大し，ネットワークトラフィックを増大させる"},{"id":"d","text":"利用者が電子メールに添付されたVBScriptファイルを実行すると感染し，PC内のパスワードを攻撃者のWebサイトへ送信したり，マルウェア付きの電子メールを他者へばらまいたりする"}]','"a"','WannaCryはSMBv1の脆弱性を悪用して拡散するワーム型ランサムウェア。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-16','exam-sg','情報資産管理・シャドーIT','standard','single_choice','【平成30年度 秋期 午前 問16】業務への利用には会社の情報システム部門の許可が本来は必要であるのに，その許可を得ずに勝手に利用されるデバイスやクラウドサービス，ソフトウェアを指す用語はどれか。','[{"id":"a","text":"シャドーIT"},{"id":"b","text":"ソーシャルエンジニアリング"},{"id":"c","text":"ダークネット"},{"id":"d","text":"バックドア"}]','"a"','シャドーITは，組織の承認や管理を受けずに業務で利用されるIT機器・サービス・ソフトウェア。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-21','exam-sg','サイバー攻撃・APT','standard','single_choice','【平成30年度 秋期 午前 問21】APTの説明はどれか。','[{"id":"a","text":"攻撃者がDoS攻撃及びDDoS攻撃を繰り返し，長期間にわたり特定組織の業務を妨害すること"},{"id":"b","text":"攻撃者が興味本位で場当たり的に，公開されている攻撃ツールや脆弱性検査ツールを悪用した攻撃を繰り返すこと"},{"id":"c","text":"攻撃者が特定の目的をもち，標的となる組織の防御策に応じて複数の攻撃方法を組み合わせ，気づかれないよう執拗に攻撃を繰り返すこと"},{"id":"d","text":"攻撃者が不特定多数への感染を目的として，複数の攻撃方法を組み合わせたマルウェアを継続的にばらまくこと"}]','"c"','APTは明確な目的を持ち，標的に合わせた複数の手法で長期間，執拗に攻撃する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-22','exam-sg','セキュア通信・TLS証明書','standard','single_choice','【平成30年度 秋期 午前 問22】A社のWebサーバはサーバ証明書を使ってTLS通信を行っている。PCからA社のWebサーバへTLSを用いてアクセスするとき，PCがサーバ証明書を入手した後に，認証局の公開鍵を利用して行う動作はどれか。','[{"id":"a","text":"暗号化通信に利用する共通鍵を，認証局の公開鍵を使って復号する"},{"id":"b","text":"暗号化通信に利用する共通鍵を生成し，認証局の公開鍵を使って暗号化する"},{"id":"c","text":"サーバ証明書の正当性を，認証局の公開鍵を使って検証する"},{"id":"d","text":"利用者が入力して送付する秘匿データを，認証局の公開鍵を使って暗号化する"}]','"c"','認証局の公開鍵で証明書の電子署名を検証し，サーバ証明書の正当性を確認する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-23','exam-sg','クラウドセキュリティ・EDoS','standard','single_choice','【平成30年度 秋期 午前 問23】従量課金制のクラウドサービスにおけるEDoS（Economic Denial of Service，又はEconomic Denial of Sustainability）攻撃の説明はどれか。','[{"id":"a","text":"カード情報の取得を目的に，金融機関が利用しているクラウドサービスに侵入する攻撃"},{"id":"b","text":"課金回避を目的に，同じハードウェア上に攻撃された別の仮想マシンに侵入し，課金機能を利用不可にする攻撃"},{"id":"c","text":"クラウドサービス利用者の経済的な損失を目的に，リソースを大量消費させる攻撃"},{"id":"d","text":"パスワード解析を目的に，クラウドサービス環境のリソースを悪用する攻撃"}]','"c"','EDoSはクラウドのリソースを大量消費させ，利用料金を増大させるなど経済的損失を狙う攻撃。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-24','exam-sg','情報隠蔽・ステガノグラフィ','standard','single_choice','【平成30年度 秋期 午前 問24】伝えたいメッセージを画像データなどのコンテンツに埋め込み，埋め込んだメッセージの存在を秘匿する技術はどれか。','[{"id":"a","text":"CAPTCHA"},{"id":"b","text":"クリックジャッキング"},{"id":"c","text":"ステガノグラフィ"},{"id":"d","text":"ストレッチング"}]','"c"','ステガノグラフィは，情報を別のデータに埋め込み，その存在自体を隠す技術。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja'),
('sg-official-2018-autumn-am-25','exam-sg','電子署名・改ざん検知','standard','single_choice','【平成30年度 秋期 午前 問25】アプリケーションソフトウェアにディジタル署名を施す目的はどれか。','[{"id":"a","text":"アプリケーションソフトウェアの改ざんを利用者が検知できるようにする"},{"id":"b","text":"アプリケーションソフトウェアの使用を特定の利用者に制限する"},{"id":"c","text":"アプリケーションソフトウェアの著作権が作成者にあることを証明する"},{"id":"d","text":"アプリケーションソフトウェアの利用者による修正や改変を不可能にする"}]','"a"','デジタル署名を検証することで，署名後にソフトウェアが改ざんされていないかを確認できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja');

INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-autumn-am-26','exam-sg','暗号技術・共通鍵暗号方式','standard','single_choice','【平成30年度 秋期 午前 問26】データベースで管理されるデータの暗号化に用いることができ，かつ，暗号化と復号とで同じ鍵を使用する暗号方式はどれか。','[{"id":"a","text":"AES"},{"id":"b","text":"PKI"},{"id":"c","text":"RSA"},{"id":"d","text":"SHA-256"}]','"a"','AESは共通鍵暗号方式であり，暗号化と復号に同じ鍵を用いる。PKIは公開鍵基盤，RSAは公開鍵暗号方式，SHA-256はハッシュ関数である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30a_sg_am_qs.pdf','ja');
